            composable("login"){
                val context = LocalContext.current
                val viewModel: LoginViewModel = viewModel(factory = LoginViewModelFactory(context.applicationContext))

                LoginScreen(
                    viewModel = viewModel,
                    onLoginSuccess = {
                        if (auth.currentUser?.email == "moderator.bayanihanspots@gmail.com"){
